"""Construye la página de pescados, mercados y riesgo portuario."""
from __future__ import annotations
import html, json
from common import DATA_DIR, OUT_DIR, banner

FISH = DATA_DIR / "gold" / "fish_supply.json"
PORTS = DATA_DIR / "gold" / "ports_marine.json"
PROVIDER = DATA_DIR / "gold" / "fish_provider_prices.json"


def main() -> int:
    banner("Construyendo página de pescados y riesgo portuario")
    if not FISH.exists() or not PORTS.exists():
        print("  Faltan contratos Gold de pescados o puertos")
        return 1
    fish = json.loads(FISH.read_text(encoding="utf-8")); ports = json.loads(PORTS.read_text(encoding="utf-8"))
    provider = json.loads(PROVIDER.read_text(encoding="utf-8")) if PROVIDER.exists() else {"products": []}
    payload = json.dumps({"fish": fish, "ports": ports, "provider": provider}, ensure_ascii=False).replace("</", "<\\/")
    page = fr'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pescados y riesgo portuario</title><style>
.kpi .risk{{color:#fff!important;font-size:16px;line-height:1.2;text-shadow:0 1px 1px #0005;padding:7px 11px}}
:root{{--bg:#f5f1e8;--card:#fffdf8;--text:#211d18;--muted:#746a5d;--line:#e7ddca;--yellow:#f4c300;--teal:#123947;--green:#278052;--amber:#a87500;--orange:#d85b17;--red:#ad2020}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}.wrap{{max-width:1240px;margin:auto;padding:22px 20px 60px}}.nav{{display:flex;gap:8px;overflow:auto;margin-bottom:12px}}.nav a{{white-space:nowrap;padding:8px 14px;border:1px solid #d4b75b;border-radius:999px;text-decoration:none;color:#4b351d;background:#fffdf8;font-weight:650}}.nav a.active{{background:var(--yellow)}}.hero{{background:linear-gradient(135deg,#071c25,#123947 62%,#6a4b19);color:white;border-radius:14px;padding:24px 28px;border-top:5px solid var(--yellow);margin-bottom:16px}}h1{{font-size:23px;margin:0 0 6px}}.hero p{{margin:0;color:#dceff3}}.meta{{margin-top:10px;color:#ffe889;font-size:12px}}.card,.kpi{{background:var(--card);border:1px solid var(--line);border-radius:12px}}.controls{{display:grid;grid-template-columns:2fr 1fr;gap:10px;padding:15px;margin-bottom:14px}}select,input{{width:100%;padding:10px;border:1px solid #cdbf9f;border-radius:8px;background:white}}.kpis{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:15px}}.kpi{{padding:14px 16px}}.kpi span{{display:block;font-size:10px;color:var(--muted);text-transform:uppercase}}.kpi b{{font-size:24px}}.kpi small{{display:block;color:var(--muted);margin-top:2px}}.fresh{{color:var(--green)!important}}.late{{color:var(--red)!important}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:15px}}.card{{padding:18px 20px;margin-bottom:15px}}h2{{font-size:14px;text-transform:uppercase;margin:0 0 12px}}.timeline input{{accent-color:#d49f00}}.ends{{display:flex;justify-content:space-between;font-size:10px;color:var(--muted)}}.risk{{display:inline-block;color:white;padding:4px 9px;border-radius:999px;font-weight:750;font-size:11px}}.low{{background:var(--green)}}.medium{{background:var(--amber)}}.high{{background:var(--orange)}}.very-high{{background:var(--red)}}table{{width:100%;border-collapse:collapse;font-size:12px}}th,td{{padding:8px;border-bottom:1px solid var(--line);text-align:left}}th{{font-size:10px;text-transform:uppercase;background:#faf5e8}}.bar{{height:6px;background:#eadfc9;border-radius:5px;overflow:hidden;margin-top:4px}}.bar i{{display:block;height:100%;background:#1d778e}}.note{{font-size:12px;color:#5c5145}}.alert{{padding:13px 15px;border-left:5px solid var(--amber);background:#fff8e5;border-radius:8px;margin-bottom:12px}}@media(max-width:800px){{.grid{{grid-template-columns:1fr}}.kpis{{grid-template-columns:1fr 1fr}}.controls{{grid-template-columns:1fr}}.wrap{{padding:12px 10px 40px}}}}</style></head><body><div class="wrap">
<nav class="nav"><a href="index.html">Clima y riesgo</a><a href="precios.html">Precios SISAP</a><a href="abastecimiento.html">Riesgo agrícola</a><a href="puertos.html">Puertos y mar</a><a class="active" href="pescados.html">Pescados y mariscos</a></nav>
<header class="hero"><h1>Pescados, mercados y riesgo portuario</h1><p>Dependencia histórica por procedencia y exposición a cierres proyectados durante los próximos 15 días.</p><div class="meta">Datos {html.escape(fish.get('data_from','—'))} a {html.escape(fish.get('data_to','—'))} · {fish.get('rows',0):,} registros · {fish.get('mapped_volume_share',0):.1%} del volumen con capitanía vinculada</div></header>
<div class="controls card"><select id="species" aria-label="Especie"></select><select id="priceSource" aria-label="Fuente del precio"><option value="provider">Precio proveedor · Google Sheet</option><option value="produce">Precio PRODUCE · mercados pesqueros</option></select><div class="timeline"><input id="day" type="range" min="0" max="14" value="0" aria-label="Día proyectado"><div class="ends"><span>Hoy</span><b id="date"></b><span>+14 días</span></div></div></div>
<div class="kpis"><div class="kpi"><span>Precio actual disponible</span><b id="priceCurrent">—</b><small id="priceFreshness"></small></div><div class="kpi"><span>Precio hace 7 días</span><b id="price7">—</b><small id="price7Date"></small></div><div class="kpi"><span>Promedio semanal</span><b id="priceWeek">—</b><small>Últimos 7 días disponibles</small></div><div class="kpi"><span>Promedio mensual</span><b id="priceMonth">—</b><small>Últimos 30 días disponibles</small></div><div class="kpi"><span>Volumen últimos 30 días</span><b id="volume">—</b></div><div class="kpi"><span>Riesgo portuario</span><b id="risk">—</b></div></div>
<div id="alert" class="alert"></div><div class="grid"><div class="card"><h2>Procedencias y exposición</h2><table><thead><tr><th>Capitanía</th><th>Participación</th><th>Prob. restricción</th><th>Señal</th></tr></thead><tbody id="origins"></tbody></table></div><div class="card"><h2>Mercados de destino</h2><table><thead><tr><th>Mercado</th><th>Participación</th></tr></thead><tbody id="markets"></tbody></table></div></div>
<div class="card"><h2>Cómo se calcula esta primera señal</h2><p class="note">Se pondera la probabilidad de restricción de cada capitanía por su participación histórica en el abastecimiento de la especie. Es una señal preventiva: todavía no incorpora vedas, temperatura del mar, desembarques recientes ni inventario de Edo Sushi.</p></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{{const source=document.getElementById('priceSource'),species=document.getElementById('species'),clean=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/\s+/g,' ').trim(),provider=new Map((DATA.provider?.products||[]).map(x=>[x.species_key,x])),cash=x=>x==null?'—':'S/ '+Number(x).toFixed(2),age=date=>date?Math.max(0,Math.floor((new Date()-new Date(date+'T12:00:00'))/86400000)):null;function showPrice(){{const fish=DATA.fish.products.find(x=>x.species===species.value),raw=source.value==='provider'?provider.get(clean(species.value)):fish&&{{latest_date:fish.produce_latest_date,current_price:fish.produce_current_price,price_7d:fish.produce_price_7d,price_7d_date:fish.produce_price_7d_date,price_week:fish.produce_price_week,price_month:fish.produce_price_month}},label=source.value==='provider'?'Proveedor / Google Sheet':'PRODUCE / mercados pesqueros';document.getElementById('priceCurrent').textContent=cash(raw?.current_price);document.getElementById('price7').textContent=cash(raw?.price_7d);document.getElementById('priceWeek').textContent=cash(raw?.price_week);document.getElementById('priceMonth').textContent=cash(raw?.price_month);document.getElementById('price7Date').textContent=raw?.price_7d_date||'';const fresh=document.getElementById('priceFreshness'),days=age(raw?.latest_date);fresh.textContent=raw?.latest_date?`${{label}} · ${{raw.latest_date}}${{raw.current_low!=null?` · rango S/ ${{raw.current_low.toFixed(2)}}–${{raw.current_high.toFixed(2)}}`:''}}`:`Sin precio disponible en ${{label}}`;fresh.className=days==null?'':days<=1?'fresh':'late'}}source.addEventListener('change',showPrice);species.addEventListener('change',()=>setTimeout(showPrice));showPrice()}});</script>
<script>const DATA={payload},portData=DATA.ports;const norm=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/\s+/g,' ').trim();const providerByKey=new Map((DATA.provider?.products||[]).map(p=>[p.species_key,p]));const products=[...DATA.fish.products].sort((a,b)=>(providerByKey.has(norm(b.species))-providerByKey.has(norm(a.species)))||a.species.localeCompare(b.species));const sel=document.getElementById('species'),day=document.getElementById('day');products.forEach(p=>sel.add(new Option(p.species+(providerByKey.has(norm(p.species))?' · precio diario':''),p.species)));function fmtPct(x){{return x==null?'—':(x*100).toFixed(1)+'%'}}function money(x){{return x==null?'—':'S/ '+Number(x).toFixed(2)}}function capRisk(cap,i){{const ps=portData.ports.filter(p=>p.captaincy===cap),vals=ps.map(p=>(portData.predictions?.[p.id]||[])[i]?.restriction_probability).filter(x=>x!=null);return vals.length?Math.max(...vals):0}}function level(x){{return x>=.55?['Muy alto','very-high']:x>=.38?['Alto','high']:x>=.2?['Medio','medium']:['Bajo','low']}}function forecastDate(i){{const first=portData.ports[0],d=(portData.waves[first?.id]||[])[i]?.date;return d||''}}function render(){{const p=products.find(x=>x.species===sel.value)||products[0],q=providerByKey.get(norm(p.species)),i=Number(day.value);sel.value=p.species;document.getElementById('date').textContent=forecastDate(i);document.getElementById('priceCurrent').textContent=money(q?.current_price);document.getElementById('price7').textContent=money(q?.price_7d);document.getElementById('priceWeek').textContent=money(q?.price_week);document.getElementById('priceMonth').textContent=money(q?.price_month);const fresh=document.getElementById('priceFreshness');fresh.textContent=q?`${{q.latest_date}} · rango S/ ${{q.current_low.toFixed(2)}}–${{q.current_high.toFixed(2)}}${{q.change_7d==null?'':` · ${{fmtPct(q.change_7d)}} vs. 7 d`}}`:'Sin observación del proveedor';fresh.className=q?(q.staleness_days<=1?'fresh':'late'):'';document.getElementById('price7Date').textContent=q?.price_7d_date||'';document.getElementById('volume').textContent=(p.volume_30_kg/1000).toFixed(1)+' t';const rows=p.origins.map(o=>({{...o,risk:capRisk(o.captaincy,i)}})),score=rows.reduce((a,o)=>a+o.share*o.risk,0),lv=level(score);document.getElementById('risk').innerHTML=`<span class="risk ${{lv[1]}}">${{lv[0]}} · ${{fmtPct(score)}}</span>`;const main=rows.sort((a,b)=>b.share-a.share)[0],mainRisk=main?level(main.risk)[0]:'—',priceNote=q?` Precio observado más reciente: <b>${{money(q.current_price)}}</b> del ${{q.latest_date}}.`:' Esta especie aún no tiene observación en la hoja del proveedor.';document.getElementById('alert').innerHTML=`<b>${{p.species}}</b>: ${{fmtPct(p.mapped_share)}} del volumen anual está vinculado a capitanías identificadas. Principal procedencia: <b>${{main?.captaincy||'—'}}</b> (${{fmtPct(main?.share)}}), con riesgo <b>${{mainRisk}}</b> para la fecha elegida.${{priceNote}}`;document.getElementById('origins').innerHTML=rows.map(o=>{{const l=level(o.risk);return`<tr><td><b>${{o.captaincy}}</b><br><small>${{o.zone}}</small></td><td>${{fmtPct(o.share)}}<div class="bar"><i style="width:${{fmtPct(o.share)}}"></i></div></td><td>${{fmtPct(o.risk)}}</td><td><span class="risk ${{l[1]}}">${{l[0]}}</span></td></tr>`}}).join('');document.getElementById('markets').innerHTML=p.markets.map(m=>`<tr><td>${{m.market}}</td><td>${{fmtPct(m.share)}}<div class="bar"><i style="width:${{fmtPct(m.share)}}"></i></div></td></tr>`).join('')}}sel.onchange=render;day.oninput=render;render();</script></body></html>'''
    OUT_DIR.mkdir(parents=True, exist_ok=True); target = OUT_DIR / "pescados.html"; target.write_text(page, encoding="utf-8")
    print(f"  -> {target} ({len(fish.get('products', []))} especies)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
